YEAR_TOKENS = {
    2026, 2025, 2024, 2023, 2022,
    2021, 2020, 2019, 2018
}


def normalize_label(text):
    return re.sub(
        r"[^a-z0-9]+",
        " ",
        str(text).lower()
    ).strip()


def parse_financial_numbers(text):
    """
    Extract financial values from a SEC table row.

    Years such as 2025/2024 are removed.
    Consecutive duplicated values caused by HTML formatting are collapsed.
    """

    pattern = r"\(?\$?\s*-?\d[\d,]*(?:\.\d+)?\)?"

    raw_numbers = re.findall(pattern, str(text))

    values = []

    for token in raw_numbers:

        token = token.strip()

        negative = (
            token.startswith("(")
            and token.endswith(")")
        )

        cleaned = (
            token
            .replace("$", "")
            .replace(",", "")
            .replace("(", "")
            .replace(")", "")
            .strip()
        )

        try:
            value = float(cleaned)
        except ValueError:
            continue

        # Remove fiscal-year labels
        if int(abs(value)) in YEAR_TOKENS:
            continue

        # Remove tiny structural values.
        # The development statement values used here are all > 100.
        if abs(value) < 100:
            continue

        if negative:
            value = -value

        values.append(value)

    # SEC HTML often creates adjacent duplicates
    deduplicated = []

    for value in values:
        if not deduplicated or value != deduplicated[-1]:
            deduplicated.append(value)

    return deduplicated


def first_two_values(evidence):
    """
    For this development filing:
    first financial value = FY2025
    second financial value = FY2024
    """

    values = parse_financial_numbers(
        evidence["text"]
    )

    if len(values) < 2:
        raise ValueError(
            f"Could not extract two fiscal-year values "
            f"from {evidence['evidence_id']}: "
            f"{evidence['text']}"
        )

    return float(values[0]), float(values[1])

