def calculate_task(
    task_id,
    selected_evidence
):

    try:

        if task_id == "revenue_growth":

            sales_2025, sales_2024 = (
                first_two_values(
                    selected_evidence["sales"]
                )
            )

            result = (
                (
                    sales_2025
                    - sales_2024
                )
                /
                sales_2024
                * 100
            )

            inputs = {
                "sales_2025":
                    sales_2025,

                "sales_2024":
                    sales_2024,
            }


        elif task_id == "operating_margin_change":

            sales_2025, sales_2024 = (
                first_two_values(
                    selected_evidence["sales"]
                )
            )

            op_2025, op_2024 = (
                first_two_values(
                    selected_evidence[
                        "operating_income"
                    ]
                )
            )

            margin_2025 = (
                op_2025
                /
                sales_2025
                * 100
            )

            margin_2024 = (
                op_2024
                /
                sales_2024
                * 100
            )

            result = (
                margin_2025
                - margin_2024
            )

            inputs = {
                "sales_2025":
                    sales_2025,

                "sales_2024":
                    sales_2024,

                "operating_income_2025":
                    op_2025,

                "operating_income_2024":
                    op_2024,

                "margin_2025_pct":
                    margin_2025,

                "margin_2024_pct":
                    margin_2024,
            }


        elif task_id == "current_ratio_change":

            assets_2025, assets_2024 = (
                first_two_values(
                    selected_evidence[
                        "current_assets"
                    ]
                )
            )

            liabilities_2025, liabilities_2024 = (
                first_two_values(
                    selected_evidence[
                        "current_liabilities"
                    ]
                )
            )

            ratio_2025 = (
                assets_2025
                /
                liabilities_2025
            )

            ratio_2024 = (
                assets_2024
                /
                liabilities_2024
            )

            result = (
                ratio_2025
                - ratio_2024
            )

            inputs = {
                "current_assets_2025":
                    assets_2025,

                "current_assets_2024":
                    assets_2024,

                "current_liabilities_2025":
                    liabilities_2025,

                "current_liabilities_2024":
                    liabilities_2024,

                "current_ratio_2025":
                    ratio_2025,

                "current_ratio_2024":
                    ratio_2024,
            }


        else:
            raise ValueError(
                f"Unknown task: {task_id}"
            )


        sign = (
            1 if result > 0
            else -1 if result < 0
            else 0
        )


        return {
            "complete": True,
            "value": float(result),
            "sign": sign,
            "inputs": inputs,
            "error": None,
        }


    except Exception as error:

        return {
            "complete": False,
            "value": None,
            "sign": None,
            "inputs": {},
            "error": str(error),
        }

