def call_ollama_agent(
    system_prompt,
    user_prompt,
    model=OLLAMA_MODEL,
    temperature=DECODER_TEMPERATURE,
    timeout=120
):
    """
    Call local Ollama chat endpoint.

    Returns raw assistant text.
    """

    payload = {
        "model": model,
        "stream": False,
        "messages": [
            {
                "role": "system",
                "content": system_prompt,
            },
            {
                "role": "user",
                "content": user_prompt,
            },
        ],
        "options": {
            "temperature": temperature
        }
    }

    response = requests.post(
        OLLAMA_URL,
        json=payload,
        timeout=timeout
    )

    response.raise_for_status()

    data = response.json()

    return (
        data
        .get("message", {})
        .get("content", "")
        .strip()
    )

