def deterministic_evidence_guard(
    evidence,
    expected_statement
):
    """
    Mechanical checks only.
    No semantic gold information is used.
    """

    checks = {}

    checks["has_evidence_id"] = (
        evidence.get(
            "evidence_id"
        )
        is not None
    )

    checks["has_label"] = (
        str(
            evidence.get(
                "label",
                ""
            )
        ).strip()
        != ""
    )

    checks["statement_match"] = (
        str(
            evidence.get(
                "statement",
                ""
            )
        )
        ==
        str(expected_statement)
    )

    try:
        values = (
            parse_financial_numbers(
                evidence["text"]
            )
        )

        checks["has_two_values"] = (
            len(values) >= 2
        )

        checks["values_numeric"] = (
            len(values) >= 2
            and all(
                isinstance(
                    x,
                    (int, float)
                )
                for x in values[:2]
            )
        )

    except Exception:

        values = []

        checks["has_two_values"] = False
        checks["values_numeric"] = False

    return {
        "passed":
            bool(
                all(
                    checks.values()
                )
            ),

        "checks":
            checks,

        "parsed_values":
            [
                float(x)
                for x in values[:3]
            ],
    }

