def safe_rate(
    numerator,
    denominator
):
    if denominator == 0:
        return np.nan

    return numerator / denominator


# --------------------------------------------------
# Ground truth:
# baseline_correct = whether FinBERT top-1 was right
#
# Verifier:
# PASS -> verifier accepts baseline
# FAIL/UNCERTAIN -> verifier challenges baseline
# --------------------------------------------------

component_df[
    "verifier_flags_problem"
] = (
    component_df[
        "verifier_verdict"
    ]
    .isin(
        [
            "FAIL",
            "UNCERTAIN"
        ]
    )
)


wrong_baseline = (
    ~component_df[
        "baseline_correct"
    ]
)

correct_baseline = (
    component_df[
        "baseline_correct"
    ]
)


# Detect wrong FinBERT selections.
detected_errors = (
    component_df.loc[
        wrong_baseline,
        "verifier_flags_problem"
    ]
    .sum()
)

total_errors = (
    wrong_baseline.sum()
)


# Dangerous case:
# baseline wrong, verifier says PASS.
false_passes = (
    (
        wrong_baseline
    )
    &
    (
        component_df[
            "verifier_verdict"
        ]
        == "PASS"
    )
).sum()


# Correct FinBERT selection incorrectly challenged.
false_rejects = (
    (
        correct_baseline
    )
    &
    (
        component_df[
            "verifier_flags_problem"
        ]
    )
).sum()


total_correct_baseline = (
    correct_baseline.sum()
)


verifier_metrics = {

    "wrong_baseline_n":
        int(total_errors),

    "correct_baseline_n":
        int(
            total_correct_baseline
        ),

    "error_detection_recall":
        safe_rate(
            detected_errors,
            total_errors
        ),

    "false_pass_rate":
        safe_rate(
            false_passes,
            total_errors
        ),

    "false_reject_rate":
        safe_rate(
            false_rejects,
            total_correct_baseline
        ),

    "baseline_component_accuracy":
        component_df[
            "baseline_correct"
        ].mean(),

    "final_component_accuracy":
        component_df[
            "final_correct"
        ].mean(),

    "top_k_recall":
        component_df[
            "top_k_recall"
        ].mean(),
}


pd.DataFrame(
    [verifier_metrics]
).T.rename(
    columns={
        0: "value"
    }
)

